#!/usr/bin/env bash
# Generated by `cargo xtask cell generate --write` from deploy/cell/charts/workspace/processes.json; edit that file, never this one.
# The Compose file's Postgres runs this once, at its first start, as its superuser.
set -euo pipefail
set_password() {
  psql -v ON_ERROR_STOP=1 -U postgres -d mandate -v role="$1" -v file="/run/secrets/$2" <<'SQL'
\set pw `cut -d: -f5 :'file'`
ALTER ROLE :"role" PASSWORD :'pw';
SQL
}
psql -v ON_ERROR_STOP=1 -U postgres -d postgres <<'SQL'
CREATE ROLE mandate_migrator LOGIN;
CREATE DATABASE mandate OWNER mandate_migrator;
SQL
psql -v ON_ERROR_STOP=1 -U postgres -d mandate -f /etc/mandate/roles.sql
set_password mandate_migrator journal-role-mandate-migrator
set_password mandate_control journal-role-mandate-control
set_password mandate_executor journal-role-mandate-executor
set_password mandate_verify journal-role-mandate-verify
set_password mandate_api journal-role-mandate-api
set_password mandate_deploy_manager journal-role-mandate-deploy-manager
set_password mandate_role_provisioner journal-role-mandate-role-provisioner
set_password mandate_connect_finish journal-role-mandate-connect-finish
set_password mandate_runtime journal-role-mandate-runtime
set_password mandate_scheduler journal-role-mandate-scheduler
set_password mandate_dispatcher journal-role-mandate-dispatcher
set_password mandate_gateway journal-role-mandate-gateway
set_password mandate_exporter journal-role-mandate-exporter
set_password mandate_data journal-role-mandate-data
